import { useState, useRef, useCallback } from 'react';

/**
 * useVoiceRecorder
 * Encapsulates MediaRecorder API for recording audio from the microphone.
 *
 * Returns:
 *  - isRecording   : boolean
 *  - audioBlob     : Blob | null  (populated after stop)
 *  - duration      : number (seconds elapsed while recording)
 *  - startRecording() : async fn – requests mic permission & starts recording
 *  - stopRecording()  : fn       – stops recording, populates audioBlob
 *  - clearRecording() : fn       – resets state
 *  - error         : string | null
 */
export function useVoiceRecorder() {
  const [isRecording, setIsRecording] = useState(false);
  const [audioBlob, setAudioBlob] = useState(null);
  const [duration, setDuration] = useState(0);
  const [error, setError] = useState(null);

  const mediaRecorderRef = useRef(null);
  const chunksRef = useRef([]);
  const timerRef = useRef(null);

  const startRecording = useCallback(async () => {
    setError(null);
    setAudioBlob(null);
    setDuration(0);
    chunksRef.current = [];

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      // Prefer webm; fall back to whatever the browser supports
      const mimeType = MediaRecorder.isTypeSupported('audio/webm;codecs=opus')
        ? 'audio/webm;codecs=opus'
        : MediaRecorder.isTypeSupported('audio/webm')
        ? 'audio/webm'
        : '';

      const recorder = new MediaRecorder(stream, mimeType ? { mimeType } : {});

      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunksRef.current.push(e.data);
      };

      recorder.onstop = () => {
        const blob = new Blob(chunksRef.current, { type: recorder.mimeType || 'audio/webm' });
        setAudioBlob(blob);
        // Stop all tracks to release the mic
        stream.getTracks().forEach((t) => t.stop());
      };

      recorder.start(100); // collect data every 100ms
      mediaRecorderRef.current = recorder;
      setIsRecording(true);

      // Timer
      const start = Date.now();
      timerRef.current = setInterval(() => {
        setDuration(Math.floor((Date.now() - start) / 1000));
      }, 500);
    } catch (err) {
      if (err.name === 'NotAllowedError') {
        setError('Microphone access denied. Please allow mic access in your browser settings.');
      } else {
        setError('Could not access microphone. Please check your device settings.');
      }
    }
  }, []);

  const stopRecording = useCallback(() => {
    clearInterval(timerRef.current);
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
      mediaRecorderRef.current.stop();
    }
    setIsRecording(false);
  }, []);

  const clearRecording = useCallback(() => {
    setAudioBlob(null);
    setDuration(0);
    setError(null);
    chunksRef.current = [];
  }, []);

  return { isRecording, audioBlob, duration, error, startRecording, stopRecording, clearRecording };
}
